// src/index.ts
async function run() {
  try {
    const username = getInput("username", { required: true });
    const password = getInput("password", { required: true });
    const serverAddress = getInput("serverAddress", { required: true });
    const projectId = getInput("projectId", { required: true });
    const releaseId = getInput("releaseId", { required: true });
    const releaseName = getInput("name");
    const releaseDescription = getInput("description");
    const isReleased = getBooleanInput("isReleased", { required: true });
    const timezone = getInput("timezone");
    const today = DateTime.utc().setZone(timezone).toFormat("yyyy-MM-dd");
    const body = {
      projectId,
      id: releaseId,
      name: releaseName ? releaseName : void 0,
      description: releaseDescription ? releaseDescription : void 0,
      archived: false,
      released: isReleased,
      releaseDate: isReleased ? today : void 0
    };
    info(`Updating release:
${JSON.stringify(body, null, 2)}`);
    const base64Credentials = btoa(`${username}:${password}`);
    const response = await fetch(`https://${serverAddress}/rest/api/latest/version/${releaseId}`, {
      method: "PUT",
      headers: {
        "Authorization": `Basic ${base64Credentials}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify(body)
    });
    if (response.ok) {
      const jsonResponse = await response.json();
      info(`Updated release ${jsonResponse.id}`);
    } else {
      error(response.statusText);
      setFailed(await response.text());
    }
  } catch (error2) {
    setFailed(error2.message);
  }
}
run();
